(function () {
const html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Investment Planning</title>\n  <!-- Google Fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:ital,wght@0,300;0,400;0,500;0,700;1,400&display=swap\" rel=\"stylesheet\">\n  <!-- Chart.js for beautiful charts -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- FontAwesome Icons -->\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  \n  <style>\n    /* Integrate provided styles.css precisely */\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root {\n      --bg: #f7f6f2; --surface: #fff; --surface2: #f2f0eb;\n      --border: #e2dfd8; --border-strong: #c8c4bb;\n      --text: #1a1916; --text2: #6b6860; --text3: #a09d98;\n      --green: #1a6b47; --green-bg: #edf7f2;\n      --blue: #1a4a6b; --blue-bg: #edf3f7;\n      --red: #6b1a1a; --red-bg: #f7eded;\n      --gold: #6b4e1a; --gold-bg: #f7f2ed;\n      --orange: #b85c00; --amber: #c97a1a;\n      --r: 6px; --rl: 10px;\n      --shadow: 0 1px 3px rgba(0,0,0,0.06);\n    }\n    body { font-family:'DM Sans',sans-serif; background:var(--bg); color:var(--text); font-size:14px; line-height:1.5; min-height:100vh; }\n\n    /* \u2500\u2500 TOPBAR \u2500\u2500 */\n    .topbar { background:var(--surface); border-bottom:1px solid var(--border); padding:0 1.5rem; display:flex; align-items:center; justify-content:space-between; height:56px; position:sticky; top:0; z-index:200; }\n    .brand { display:flex; align-items:center; gap:10px; }\n    .brand-mark { width:28px; height:28px; background:var(--text); border-radius:6px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }\n    .brand-mark svg { width:14px; height:14px; fill: white; }\n    .brand-name { font-size:14px; font-weight:500; letter-spacing:-0.01em; }\n    .brand-sub { font-size:12px; color:var(--text3); margin-left:2px; }\n    .pill-nav { display:flex; background:var(--surface2); border-radius:20px; padding:3px; gap:2px; }\n    .pill-btn { padding:5px 16px; border-radius:16px; border:none; background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; font-weight:400; transition:all .15s; }\n    .pill-btn.active { background:var(--surface); color:var(--text); font-weight:500; box-shadow:0 1px 2px rgba(0,0,0,.08); }\n\n    /* \u2500\u2500 PAGE SHELLS \u2500\u2500 */\n    .page { display:none; }\n    .page.active { display:flex; min-height:calc(100vh - 56px); }\n\n    /* \u2500\u2500 ENTRY LAYOUT \u2500\u2500 */\n    .sidebar { width:260px; flex-shrink:0; background:var(--surface); border-right:1px solid var(--border); position:sticky; top:56px; height:calc(100vh - 56px); overflow-y:auto; padding:1.25rem 0; }\n    .main-area { flex:1; padding:2rem; overflow-y:auto; min-width:0; }\n\n    /* sidebar nav */\n    .sb-label { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); padding:0 1.25rem; margin-bottom:.5rem; }\n    .sb-item { display:flex; align-items:center; gap:10px; padding:9px 1.25rem; cursor:pointer; border-left:2px solid transparent; transition:all .12s; font-size:13px; color:var(--text2); text-decoration:none; }\n    .sb-item:hover { background:var(--surface2); color:var(--text); }\n    .sb-item.active { border-left-color:var(--text); color:var(--text); font-weight:500; background:var(--surface2); }\n    .sb-dot { width:6px; height:6px; border-radius:50%; flex-shrink:0; }\n    .d1 { background:var(--green); } .d2 { background:var(--blue); } .d3 { background:var(--gold); } .d4 { background:var(--text3); }\n\n    /* progress */\n    .prog-wrap { padding:1.25rem 1.25rem .75rem; }\n    .prog-top { display:flex; justify-content:space-between; font-size:11px; color:var(--text3); margin-bottom:6px; }\n    .prog-track { height:3px; background:var(--surface2); border-radius:2px; overflow:hidden; }\n    .prog-fill { height:100%; background:var(--text); border-radius:2px; width:0%; transition:width .4s; }\n\n    /* per-segment sidebar summaries */\n    .seg-sum { display:none; margin:0 1rem .75rem; }\n    .seg-sum.on { display:block; }\n    .ss-head { color:#fff; font-size:10px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; padding:6px 10px; border-radius:var(--r) var(--r) 0 0; }\n    .ss-body { background:var(--surface2); border-radius:0 0 var(--r) var(--r); padding:8px 10px; border:1px solid var(--border); border-top:none; }\n    .ss-row { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; color:var(--text2); border-bottom:1px solid var(--border); }\n    .ss-row:last-child { border-bottom:none; }\n    .ss-row.neg { color:var(--red); }\n    .ss-v { font-family:'DM Mono',monospace; font-size:11px; color:var(--text); }\n    .ss-b { font-weight:500; }\n    .ss-div { height:1px; background:var(--border-strong); margin:5px 0; }\n    .ss-tot { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; font-weight:500; }\n    .positive { color:var(--green); } .negative { color:var(--red); } .neutral { color:var(--blue); } .warning { color:var(--amber); }\n\n    /* \u2500\u2500 SEGMENT CONTENT \u2500\u2500 */\n    .segment { display:none; }\n    .segment.active { display:block; }\n    .seg-hdr { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:1.75rem; }\n    .seg-tag { display:inline-flex; align-items:center; padding:3px 10px; border-radius:20px; font-size:11px; font-weight:500; margin-bottom:6px; }\n    .t1{background:var(--green-bg);color:var(--green);} .t2{background:var(--blue-bg);color:var(--blue);} .t3{background:var(--gold-bg);color:var(--gold);} .t4{background:var(--surface2);color:var(--text2);}\n    .seg-title { font-size:22px; font-weight:300; letter-spacing:-.03em; }\n    .seg-desc { font-size:13px; color:var(--text3); margin-top:4px; }\n    .seg-tot-box { text-align:right; background:var(--surface2); border-radius:var(--rl); padding:10px 16px; }\n    .tot-label { font-size:11px; color:var(--text3); }\n    .tot-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n\n    /* cards */\n    .card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); margin-bottom:1.25rem; overflow:hidden; box-shadow:var(--shadow); }\n    .ch { display:flex; align-items:center; justify-content:space-between; padding:14px 18px; cursor:pointer; user-select:none; border-bottom:1px solid transparent; transition:background .12s; }\n    .ch:hover { background:var(--surface2); }\n    .ch.open { border-bottom-color:var(--border); }\n    .ch-left { display:flex; align-items:center; gap:12px; }\n    .ci { width:28px; height:28px; border-radius:6px; display:flex; align-items:center; justify-content:center; font-size:13px; flex-shrink:0; }\n    .ci1{background:var(--green-bg); color:var(--green);} .ci2{background:var(--blue-bg); color:var(--blue);} .ci3{background:var(--gold-bg); color:var(--gold);} .ci-r{background:var(--red-bg); color:var(--red);} .ci-g{background:var(--surface2); color:var(--text2);}\n    .ch-title { font-size:14px; font-weight:500; }\n    .ch-sub { font-size:11px; color:var(--text3); margin-top:1px; }\n    .ch-right { display:flex; align-items:center; gap:10px; }\n    .ch-sum { font-family:'DM Mono',monospace; font-size:13px; color:var(--text2); }\n    .chev { width:16px; height:16px; color:var(--text3); transition:transform .2s; flex-shrink:0; }\n    .chev.open { transform:rotate(180deg); }\n    .cb { display:none; padding:16px 18px; }\n    .cb.open { display:block; }\n\n    /* fields */\n    .f-static { display:grid; grid-template-columns:240px 1fr ; gap:12px; align-items:center; padding:10px 0; border-bottom:1px solid var(--border); }\n    .f-static:last-of-type { border-bottom:none; }\n    .f-label { font-size:13px; font-weight: 500; }\n    .f-sub { font-size:11px; color:var(--text3); font-weight: normal; margin-top: 2px; }\n    .pfx-wrap { position:relative; width: 100%; }\n    .pfx { position:absolute; left:12px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; font-weight: 500; }\n    .inp { width:100%; height:36px; border:1px solid var(--border); border-radius:var(--r); padding:0 12px; font-size:13px; font-family:'DM Mono',monospace; color:var(--text); background:var(--surface); text-align:right; transition:border-color .12s; }\n    .inp:focus { outline:none; border-color:var(--text); }\n    .inp.pl { padding-left:36px; text-align:left; }\n    .inp-t { height:36px; border:1px solid var(--border); border-radius:var(--r); padding:0 12px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface); width:100%; transition:border-color .12s; }\n    .inp-t:focus { outline:none; border-color:var(--text); }\n    \n    /* table style list items instead of standard dynamic inputs */\n    .table-container { overflow-x: auto; margin-top: 10px; border: 1px solid var(--border); border-radius: var(--r); }\n    .inv-table { width: 100%; border-collapse: collapse; min-width: 800px; text-align: left; }\n    .inv-table th { background: var(--surface2); padding: 10px 12px; font-size: 11px; font-weight: 500; text-transform: uppercase; color: var(--text2); border-bottom: 1px solid var(--border); }\n    .inv-table td { padding: 10px 12px; border-bottom: 1px solid var(--border-strong); vertical-align: middle; background: var(--surface); }\n    .inv-table tr:last-child td { border-bottom: none; }\n    \n    .exp-rows { margin-top:10px; }\n    .exp-row-4 { display:grid; grid-template-columns:130px 1fr 150px 30px; gap:6px; align-items:center; margin-bottom:6px; animation:fi .15s ease; }\n    @keyframes fi { from{opacity:0;transform:translateY(-4px)} to{opacity:1;transform:translateY(0)} }\n    .btn-rm { width:32px; height:32px; border:1px solid var(--border); border-radius:var(--r); background:transparent; cursor:pointer; color:var(--text3); display:flex; align-items:center; justify-content:center; font-size:14px; transition:all .12s; }\n    .btn-rm:hover { border-color:var(--red); color:var(--red); background:var(--red-bg); }\n    .btn-add { display:flex; align-items:center; justify-content:center; gap:6px; padding:8px 12px; border:1px dashed var(--border-strong); border-radius:var(--r); background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; margin-top:12px; width:100%; transition:all .12s; font-weight: 500; }\n    .btn-add:hover { border-color:var(--text); color:var(--text); background:var(--surface2); }\n    \n    /* nav buttons */\n    .seg-nav { display:flex; justify-content:space-between; align-items:center; margin-top:2rem; padding-top:1.5rem; border-top:1px solid var(--border); }\n    .btn-nav { display:flex; align-items:center; gap:6px; padding:9px 18px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; transition:all .12s; }\n    .btn-nav:hover { border-color:var(--text); color:var(--text); }\n    .btn-pri { background:var(--text); color:#fff; border-color:var(--text); }\n    .btn-pri:hover { background:#333; }\n\n    /* \u2500\u2500 ANALYSIS PAGE \u2500\u2500 */\n    #page-analysis .main-area { max-width:1100px; margin:0 auto; }\n    .a-header { margin-bottom:1.75rem; display:flex; align-items:flex-start; justify-content:space-between; gap:1rem; margin-bottom:1.75rem; flex-wrap:wrap; }\n    .a-title { font-size:28px; font-weight:300; letter-spacing:-.03em; }\n    .a-sub { font-size:13px; color:var(--text3); margin-top:4px; }\n    .sec-title { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); margin-bottom:.75rem; margin-top:1.5rem; }\n\n    /* quadrant */\n    .quad-grid { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; margin-bottom:1rem; }\n    .quad-card { border-radius:var(--rl); overflow:hidden; border:1px solid var(--border); cursor:pointer; transition:transform .15s, box-shadow .15s; }\n    .quad-card:hover { transform:translateY(-2px); box-shadow:0 6px 20px rgba(0,0,0,.1); }\n    .quad-card:active { transform:translateY(0); box-shadow:none; }\n    .q-hint { font-size:10px; color:rgba(255,255,255,.7); font-style:italic; float:right; font-weight:400; letter-spacing:0; }\n    .q-head { padding:8px 12px; font-size:11px; font-weight:500; letter-spacing:.05em; text-transform:uppercase; color:#fff; }\n    .qg{background:#1a6b47;} .qr{background:#8b2020;} .qb{background:#1a4a6b;} .qo{background:#b85c00;}\n    .q-body { background:var(--surface); padding:10px 12px; }\n    .q-row { display:flex; justify-content:space-between; padding:3px 0; font-size:12px; color:var(--text2); border-bottom:1px solid var(--surface2); }\n    .q-row:last-child { border-bottom:none; }\n    .q-val { font-family:'DM Mono',monospace; font-size:12px; font-weight:500; color:var(--text); }\n    .q-div { height:1px; background:var(--border); margin:6px 0; }\n    .q-foot { display:flex; justify-content:space-between; padding:4px 0 0; font-size:12px; font-weight:500; }\n    .q-fv { font-family:'DM Mono',monospace; font-size:13px; font-weight:500; }\n\n    /* matrix */\n    .mx-grid { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .mx-item { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .mx-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:3px; }\n    .mx-fml { font-size:10px; color:var(--text3); opacity:.7; margin-bottom:8px; font-style:italic; }\n    .mx-val { font-size:22px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .mx-sub { font-size:11px; color:var(--text3); margin-top:3px; }\n\n    /* kpi strip */\n    .kpi-grid { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .kpi { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .kpi-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:6px; }\n    .kpi-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .kpi-sub { font-size:11px; color:var(--text3); margin-top:4px; }\n\n    /* analysis cards */\n    .a-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1.25rem; margin-bottom:1rem; }\n    .a-card-title { font-size:13px; font-weight:500; margin-bottom:1rem; display:flex; align-items:center; gap:8px; }\n    .a-dot { width:8px; height:8px; border-radius:50%; flex-shrink:0; }\n    .two-col { display:grid; grid-template-columns:1fr 1fr; gap:1rem; margin-bottom:1rem; }\n    .chart-wrap { position:relative; min-height: 200px; display: flex; align-items: center; justify-content: center; }\n    .bar-list { display:flex; flex-direction:column; gap:10px; }\n    .bar-item-top { display:flex; justify-content:space-between; margin-bottom:5px; font-size:12px; }\n    .bar-lbl { color:var(--text2); }\n    .bar-val { font-family:'DM Mono',monospace; font-weight:500; }\n    .bar-track { height:6px; background:var(--surface2); border-radius:4px; overflow:hidden; }\n    .bar-fill { height:100%; border-radius:4px; transition:width .8s; }\n    .bk-table { width:100%; border-collapse:collapse; }\n    .bk-table th { font-size:11px; font-weight:500; color:var(--text3); text-align:left; padding:0 0 8px; border-bottom:1px solid var(--border); }\n    .bk-table th:last-child { text-align:right; }\n    .bk-table td { padding:8px 0; font-size:13px; border-bottom:1px solid var(--surface2); vertical-align:middle; }\n    .bk-table td:last-child { text-align:right; font-family:'DM Mono',monospace; font-weight:500; }\n    .bk-table tr:last-child td { border-bottom:none; }\n    .cat-badge { display:inline-flex; align-items:center; gap:5px; }\n    .cat-dot { width:6px; height:6px; border-radius:50%; }\n    .ratio-item { display:flex; align-items:center; gap:8px; margin-bottom:8px; }\n    .ratio-lbl { font-size:12px; color:var(--text2); width:130px; flex-shrink:0; }\n    .ratio-track { flex:1; background:var(--surface2); height:8px; border-radius:4px; overflow:hidden; }\n    .ratio-fill { height:100%; border-radius:4px; }\n    .ratio-pct { font-size:12px; font-family:'DM Mono',monospace; width:42px; text-align:right; }\n    \n    .kpi-val.surplus { color:#1a6b47; font-weight:700; }\n    .kpi-val.deficit { color:#8b2020; font-weight:700; }\n\n    /* reset/top actions */\n    .btn-reset-seg { display:inline-flex; align-items:center; gap:5px; padding:5px 12px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; }\n    .btn-reset-seg:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .btn-reset-data { display:inline-flex; align-items:center; gap:4px; padding:4px 9px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; margin-left:6px; }\n    .btn-reset-data:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .seg-hdr-actions { display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:flex-end; }\n\n    /* Commentary boxes */\n    .commentary-block { margin-top: 1.5rem; padding-top: 1.25rem; border-top: 1px dashed var(--border); }\n    .commentary-box { width:100%; min-height:80px; border:1px solid var(--border); border-radius:var(--rl); padding:10px 12px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface2); resize:vertical; line-height:1.5; transition:border-color .12s; }\n    .commentary-box:focus { outline:none; border-color:var(--text); background:var(--surface); }\n    .commentary-box::placeholder { color:var(--text3); }\n    .commentary-lbl { font-size:11px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; color:var(--text2); margin-bottom:6px; display:flex; align-items:center; gap:6px; }\n    .commentary-char { font-size:10px; color:var(--text3); margin-left:auto; font-weight:400; letter-spacing:0; text-transform:none; }\n    .commentary-print { display:none; font-size:11px; color:var(--text2); font-style:italic; margin-top:6px; white-space:pre-wrap; }\n\n    /* Print/PDF button style */\n    .btn-pdf { display:inline-flex; align-items:center; gap:7px; padding:8px 18px; background:var(--text); color:#fff; border:none; border-radius:var(--r); font-size:13px; font-family:'DM Sans',sans-serif; font-weight:500; cursor:pointer; transition:opacity .15s; white-space:nowrap; flex-shrink:0; }\n    .btn-pdf:hover { opacity:.85; }\n\n    /* Toggle switches (iOS Style) */\n    .toggle-wrap { display: flex; align-items: center; justify-content: space-between; background: var(--surface); padding: 14px 18px; border-radius: var(--rl); border: 1px solid var(--border); margin-bottom: 1.5rem; box-shadow: var(--shadow); }\n    .toggle-label-group { display: flex; flex-direction: column; }\n    .toggle-title { font-size: 14px; font-weight: 500; color: var(--text); }\n    .toggle-desc { font-size: 11px; color: var(--text3); margin-top: 2px; }\n    .switch { position: relative; display: inline-block; width: 44px; height: 24px; }\n    .switch input { opacity: 0; width: 0; height: 0; }\n    .slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: var(--border-strong); transition: .2s; border-radius: 24px; }\n    .slider:before { position: absolute; content: \"\"; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; transition: .2s; border-radius: 50%; }\n    input:checked + .slider { background-color: var(--green); }\n    input:checked + .slider:before { transform: translateX(20px); }\n\n    /* WACC display dashboard component */\n    .wacc-panel { margin-top: 1.5rem; animation: fi .2s ease; display: none; }\n    .wacc-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--rl); padding: 1.5rem; box-shadow: var(--shadow); }\n    .wacc-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin-top: 1rem; }\n    .wacc-item { background: var(--surface2); padding: 12px 16px; border-radius: var(--r); border: 1px solid var(--border); }\n    .wacc-lbl { font-size: 11px; color: var(--text3); text-transform: uppercase; letter-spacing: 0.05em; }\n    .wacc-val { font-size: 20px; font-weight: 700; font-family: 'DM Mono', monospace; margin-top: 4px; }\n\n    /* Custom classes for alignment and spacing */\n    .text-right { text-align: right; }\n    .text-center { text-align: center; }\n    .mt-4 { margin-top: 1rem; }\n    .mb-4 { margin-bottom: 1rem; }\n    .d-none { display: none !important; }\n    .flex { display: flex; }\n    .flex-col { flex-direction: column; }\n    .align-center { align-items: center; }\n    .justify-between { justify-content: space-between; }\n    .gap-2 { gap: 8px; }\n    .gap-3 { gap: 12px; }\n    .bold { font-weight: 500; }\n    .mono { font-family: 'DM Mono', monospace; }\n    .relative { position: relative; }\n    .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }\n    @media(max-width: 768px) {\n      .grid-2 { grid-template-columns: 1fr; }\n    }\n\n    /* Print styling support */\n    @media print {\n      * { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }\n      body { background:#f7f6f2 !important; margin:0; }\n      .topbar, .sidebar, .btn-pdf, .pdf-overlay, .btn-reset-seg, .btn-reset-data, .seg-nav, .commentary-box, .commentary-lbl, .commentary-char, .pill-nav, .btn-add, .btn-rm, .btn-pri, button { display:none !important; }\n      .page { display:block !important; min-height:auto !important; }\n      .main-area { padding:12px !important; max-width:100% !important; }\n      .card { break-inside:avoid; page-break-inside:avoid; border: 1px solid #e2dfd8 !important; }\n      .inv-table { min-width: 100% !important; }\n      .commentary-print { display:block !important; border-top: 1px dashed var(--border); padding-top: 10px; }\n    }\n  </style>\n\n<style id=\"planning-suite-frame-overrides\">\n  html, body { min-height: 100%; }\n  body { margin: 0 !important; padding: 0 !important; background: #f7f6f2 !important; }\n  .topbar, .sidebar { display: none !important; }\n  .page.active { min-height: 100vh !important; display: block !important; }\n  .main-area { width: 100% !important; max-width: 1240px !important; margin: 0 auto !important; padding: 2rem !important; box-sizing: border-box !important; }\n  .container { max-width: 1240px !important; padding: 2rem !important; }\n  @media (max-width: 900px) { .main-area, .container { padding: 1rem !important; } .f-static { grid-template-columns: 1fr !important; } }\n</style>\n</head>\n<body>\n\n  <!-- TOPBAR -->\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <div class=\"brand-mark\">\n        <!-- SVG Financial Leaf/Growth Emblem -->\n        <svg viewBox=\"0 0 24 24\">\n          <path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 17h-2v-2h2v2zm2.07-7.75l-.9.92C13.45 12.9 13 13.5 13 15h-2v-.5c0-1.1.45-2.1 1.17-2.83l1.24-1.26c.37-.36.59-.86.59-1.41 0-1.1-.9-2-2-2s-2 .9-2 2H7c0-2.76 2.24-5 5-5s5 2.24 5 5c0 1.04-.42 1.99-1.07 2.75z\"/>\n        </svg>\n      </div>\n      <div>\n        <span class=\"brand-name\">ProsperFlow</span>\n        <span class=\"brand-sub\">Premium Financial Advisory Suite</span>\n      </div>\n    </div>\n    \n    <div class=\"pill-nav\">\n      <button class=\"pill-btn active\" onclick=\"switchMainPage('page-entry')\">Planner</button>\n      <button class=\"pill-btn\" onclick=\"switchMainPage('page-analysis')\">Analysis Report</button>\n    </div>\n\n    <div class=\"flex align-center gap-2\">\n      <button class=\"btn-pdf\" onclick=\"window.print()\">\n        <i class=\"fa-solid fa-print\"></i> Print Report\n      </button>\n    </div>\n  </header>\n\n  <!-- APP SHELL -->\n  <div id=\"appShell\" style=\"display: flex;\">\n    \n    <!-- SIDEBAR -->\n    <aside class=\"sidebar\">\n      <div class=\"prog-wrap\">\n        <div class=\"prog-top\">\n          <span>Planning Progress</span>\n          <span id=\"prog-pct\">0%</span>\n        </div>\n        <div class=\"prog-track\">\n          <div class=\"prog-fill\" id=\"prog-bar\" style=\"width: 0%;\"></div>\n        </div>\n      </div>\n\n      <div class=\"sb-label\">Portfolio Modules</div>\n      \n      <a href=\"#\" class=\"sb-item active\" id=\"sb-existing\" onclick=\"scrollToElement('existing-inv-section')\">\n        <span class=\"sb-dot d1\"></span>\n        <span>Existing Portfolio</span>\n      </a>\n      \n      <a href=\"#\" class=\"sb-item\" id=\"sb-planner\" onclick=\"scrollToElement('new-inv-section')\">\n        <span class=\"sb-dot d2\"></span>\n        <span>Target Goal Planner</span>\n      </a>\n\n      <div style=\"margin-top: 1.5rem;\" class=\"sb-label\">Inflation Benchmark</div>\n      <div style=\"padding: 0 1.25rem;\">\n        <div class=\"pfx-wrap\">\n          <span class=\"pfx\"><i class=\"fa-solid fa-triangle-exclamation\" style=\"color: var(--amber)\"></i></span>\n          <input type=\"number\" id=\"inflation-rate\" class=\"inp\" value=\"3.0\" step=\"0.1\" style=\"padding-left: 28px; text-align: right;\" onchange=\"calculateAllExistingCAGR(); updateAnalysisDashboard();\">\n          <span style=\"position: absolute; right: 10px; top: 50%; transform: translateY(-50%); font-size: 11px; color: var(--text3);\">%</span>\n        </div>\n        <div style=\"font-size: 10px; color: var(--text3); margin-top: 4px; line-height: 1.3;\">\n          Used to evaluate whether your overall returns beat standard purchasing power erosion.\n        </div>\n      </div>\n\n      <!-- Quick Segment Summary Widget -->\n      <div class=\"seg-sum on\" style=\"margin-top: 1.5rem;\">\n        <div class=\"ss-head qg\">Active Session Metrics</div>\n        <div class=\"ss-body\">\n          <div class=\"ss-row\">\n            <span>Existing Investments</span>\n            <span class=\"ss-v\" id=\"side-total-existing\">RM 0.00</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Overall WACC/Return</span>\n            <span class=\"ss-v ss-b\" id=\"side-wacc-val\">0.00%</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Goals Evaluated</span>\n            <span class=\"ss-v\" id=\"side-goals-count\">0</span>\n          </div>\n          <div class=\"ss-div\"></div>\n          <div class=\"ss-tot\">\n            <span>Inflation Margin</span>\n            <span id=\"side-inflation-margin\" class=\"positive\">0.00%</span>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- MAIN PLANNED ENTRY AREA -->\n    <main class=\"main-area page active\" id=\"page-entry\">\n      <div style=\"width: 100%; max-width: 1100px; margin: 0 auto;\">\n        \n        <!-- Segment Header -->\n        <div class=\"seg-hdr\">\n          <div>\n            <span class=\"seg-tag t1\"><i class=\"fa-solid fa-chart-line\"></i> Asset Management</span>\n            <h1 class=\"seg-title\">Investment Analysis & Goal Formulation</h1>\n            <p class=\"seg-desc\">Configure your current asset holdings to calculate weighted returns, and set future objectives to address wealth generation target gaps.</p>\n          </div>\n          <div class=\"seg-hdr-actions\">\n            <button class=\"btn-reset-seg\" onclick=\"resetAllFormData()\">\n              <i class=\"fa-solid fa-rotate-left\"></i> Reset Workspace\n            </button>\n          </div>\n        </div>\n\n        <!-- TOGGLE 1: EXISTING INVESTMENTS -->\n        <div class=\"toggle-wrap\">\n          <div class=\"toggle-label-group\">\n            <span class=\"toggle-title\">Do you have existing investments?</span>\n            <span class=\"toggle-desc\">Toggle on to construct an asset ledger and compute the Weighted Average Cost of Return (WACR/WACC).</span>\n          </div>\n          <label class=\"switch\">\n            <input type=\"checkbox\" id=\"toggle-existing\" onchange=\"toggleExistingContainer()\">\n            <span class=\"slider\"></span>\n          </label>\n        </div>\n\n        <!-- EXISTING INVESTMENTS CONTAINER -->\n        <div id=\"existing-inv-section\" style=\"display: none;\">\n          <div class=\"card\">\n            <!-- Header -->\n            <div class=\"ch open\" onclick=\"toggleCardBody(this)\">\n              <div class=\"ch-left\">\n                <div class=\"ci ci1\"><i class=\"fa-solid fa-wallet\"></i></div>\n                <div>\n                  <div class=\"ch-title\">Current Investment Asset Matrix</div>\n                  <div class=\"ch-sub\">Add all active shares, unit trusts, property, or retirement accounts.</div>\n                </div>\n              </div>\n              <div class=\"ch-right\">\n                <span class=\"ch-sum\" id=\"total-existing-val-header\">RM 0.00 Total</span>\n                <i class=\"fa-solid fa-chevron-down chev open\"></i>\n              </div>\n            </div>\n\n            <!-- Expandable Body -->\n            <div class=\"cb open\">\n              <div class=\"table-container\">\n                <table class=\"inv-table\" id=\"existing-table\">\n                  <thead>\n                    <tr>\n                      <th style=\"width: 50px;\">#</th>\n                      <th style=\"width: 250px;\">Name of Investment</th>\n                      <th>Initial Inv. (PV)</th>\n                      <th>Annual Regular (PMT)</th>\n                      <th style=\"width: 100px;\">Start Year</th>\n                      <th style=\"width: 100px;\">Current Year</th>\n                      <th>Current Value (FV)</th>\n                      <th style=\"width: 110px;\" class=\"text-right\">CAGR</th>\n                      <th style=\"width: 50px;\"></th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"existing-tbody\">\n                    <!-- Dynamic Rows Insertion -->\n                  </tbody>\n                </table>\n              </div>\n\n              <button class=\"btn-add\" onclick=\"addExistingRow()\">\n                <i class=\"fa-solid fa-plus\"></i> Add New Investment Position\n              </button>\n\n              <div style=\"margin-top: 1.5rem; display: flex; justify-content: flex-end; gap: 10px;\">\n                <button class=\"btn-nav btn-pri\" onclick=\"calculateWACC()\">\n                  <i class=\"fa-solid fa-calculator\"></i> Calculate WACC\n                </button>\n              </div>\n\n              <!-- Weighted Average Cost of Return (WACC) Display Panel -->\n              <div class=\"wacc-panel\" id=\"wacc-panel\">\n                <div class=\"grp-label\">WACC SUMMARY ANALYSIS</div>\n                \n                <div class=\"table-container\" style=\"margin-bottom: 1.5rem;\">\n                  <table class=\"inv-table\" style=\"min-width: 600px;\">\n                    <thead>\n                      <tr>\n                        <th>#</th>\n                        <th>Name of Investment</th>\n                        <th class=\"text-right\">Market Value (RM)</th>\n                        <th class=\"text-right\">CAGR (%)</th>\n                        <th class=\"text-right\">% of Total Portfolio</th>\n                        <th class=\"text-right\">WACC Weight Contribution</th>\n                      </tr>\n                    </thead>\n                    <tbody id=\"wacc-summary-tbody\">\n                      <!-- Filled dynamically -->\n                    </tbody>\n                  </table>\n                </div>\n\n                <div class=\"wacc-grid\">\n                  <div class=\"wacc-item\" style=\"border-left: 4px solid var(--text);\">\n                    <div class=\"wacc-lbl\">Total Market Value</div>\n                    <div class=\"wacc-val\" id=\"summary-total-mv\">RM 0.00</div>\n                  </div>\n                  <div class=\"wacc-item\" id=\"summary-wacc-card\" style=\"border-left: 4px solid var(--blue);\">\n                    <div class=\"wacc-lbl\">Weighted Portfolio Return</div>\n                    <div class=\"wacc-val\" id=\"summary-wacc-val\">0.00%</div>\n                  </div>\n                  <div class=\"wacc-item\" id=\"summary-benchmark-card\" style=\"border-left: 4px solid var(--green);\">\n                    <div class=\"wacc-lbl\">vs Inflation Benchmark</div>\n                    <div class=\"wacc-val\" id=\"summary-benchmark-val\">Beating (0.00%)</div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n\n        <!-- TOGGLE 2: PLAN NEW INVESTMENTS -->\n        <div class=\"toggle-wrap\" style=\"margin-top: 2rem;\">\n          <div class=\"toggle-label-group\">\n            <span class=\"toggle-title\">Do you want to plan new investments?</span>\n            <span class=\"toggle-desc\">Toggle on to frame goal-oriented strategies, calculate compounding yields, and check targeting metrics.</span>\n          </div>\n          <label class=\"switch\">\n            <input type=\"checkbox\" id=\"toggle-new\" onchange=\"toggleNewContainer()\">\n            <span class=\"slider\"></span>\n          </label>\n        </div>\n\n        <!-- NEW INVESTMENTS PLANNING SECTION -->\n        <div id=\"new-inv-section\" style=\"display: none;\">\n          <div class=\"seg-hdr\" style=\"margin-bottom: 1rem;\">\n            <div>\n              <h2 class=\"seg-title\" style=\"font-size: 18px;\">Target-Driven Investment Models</h2>\n              <p class=\"seg-desc\">Configure separate accumulation schemes to test if regular savings compound sufficiently to fulfill prospective horizons.</p>\n            </div>\n          </div>\n\n          <div id=\"new-goals-container\">\n            <!-- Goal Cards Inserted Dynamically -->\n          </div>\n\n          <button class=\"btn-add\" onclick=\"addNewGoalCard()\" style=\"border-style: solid; background: var(--surface); margin-bottom: 2rem;\">\n            <i class=\"fa-solid fa-circle-plus\"></i> Formulate a New Financial Objective\n          </button>\n        </div>\n\n        <!-- Navigation Section -->\n        <div class=\"seg-nav\">\n          <div style=\"font-size: 12px; color: var(--text3);\">\n            Ensure all calculated figures represent annualized rates.\n          </div>\n          <button class=\"btn-nav btn-pri\" onclick=\"goToReportPage()\">\n            Go to Report View <i class=\"fa-solid fa-arrow-right\"></i>\n          </button>\n        </div>\n\n      </div>\n    </main>\n\n    <!-- ANALYSIS REPORT PAGE -->\n    <main class=\"main-area page\" id=\"page-analysis\">\n      <div style=\"width: 100%;\">\n        \n        <div class=\"a-header\">\n          <div class=\"a-header-left\">\n            <span class=\"seg-tag t3\"><i class=\"fa-solid fa-trophy\"></i> Advisory Insight</span>\n            <h1 class=\"a-title\">Consolidated Performance & Strategy Analysis</h1>\n            <p class=\"a-sub\">Holistic metrics review for target returns, inflation preservation, and strategic portfolio optimization.</p>\n          </div>\n          <button class=\"btn-nav\" onclick=\"switchMainPage('page-entry'); window.scrollTo({ top: 0, behavior: 'smooth' });\">\n            <i class=\"fa-solid fa-arrow-left\"></i> Back\n          </button>\n\n        </div>\n\n        <!-- MATRIX CARDS -->\n        <div class=\"mx-grid\">\n          <div class=\"mx-item\">\n            <div class=\"mx-lbl\">Total Current Assets</div>\n            <div class=\"mx-fml\">Aggregate Holdings Value</div>\n            <div class=\"mx-val\" id=\"mx-current-assets\">RM 0.00</div>\n            <div class=\"mx-sub\" id=\"mx-assets-count\">0 Positions</div>\n          </div>\n          <div class=\"mx-item\">\n            <div class=\"mx-lbl\">Portfolio Return (WACR)</div>\n            <div class=\"mx-fml\">Weighted Asset Performance</div>\n            <div class=\"mx-val\" id=\"mx-portfolio-return\">0.00%</div>\n            <div class=\"mx-sub\" id=\"mx-wacc-comparison\">No comparison</div>\n          </div>\n          <div class=\"mx-item\">\n            <div class=\"mx-lbl\">Planned Future Savings</div>\n            <div class=\"mx-fml\">Target Wealth Accumulations</div>\n            <div class=\"mx-val\" id=\"mx-planned-fv\">RM 0.00</div>\n            <div class=\"mx-sub\" id=\"mx-goals-total\">0 Objectives</div>\n          </div>\n          <div class=\"mx-item\">\n            <div class=\"mx-lbl\">Goal Accomplishment Rate</div>\n            <div class=\"mx-fml\">FV projected vs. Targets</div>\n            <div class=\"mx-val\" id=\"mx-accomplish-rate\">0%</div>\n            <div class=\"mx-sub\" id=\"mx-funding-status\">No goals planned</div>\n          </div>\n        </div>\n\n        <!-- TWO COLUMNS FOR CHARTS & LISTS -->\n        <div class=\"grid-2\">\n          \n          <!-- Column Left: Portfolio Allocations & WACC -->\n          <div class=\"a-card\">\n            <div class=\"a-card-title\">\n              <span class=\"a-dot d1\"></span>\n              Portfolio Composition & Returns Weighting\n            </div>\n            <div class=\"chart-wrap\" style=\"margin-bottom: 1.5rem;\">\n              <canvas id=\"portfolioChart\" style=\"max-height: 250px; max-width: 250px;\"></canvas>\n            </div>\n            \n            <div class=\"table-container\">\n              <table class=\"bk-table\">\n                <thead>\n                  <tr>\n                    <th>Asset Class</th>\n                    <th style=\"text-align: right;\">Value</th>\n                    <th style=\"text-align: right;\">Return</th>\n                    <th style=\"text-align: right;\">Weight</th>\n                  </tr>\n                </thead>\n                <tbody id=\"analysis-portfolio-rows\">\n                  <tr>\n                    <td colspan=\"4\" class=\"text-center\" style=\"color: var(--text3); padding: 20px;\">No investment data available. Please add positions.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Column Right: Growth Objective Projections -->\n          <div class=\"a-card\">\n            <div class=\"a-card-title\">\n              <span class=\"a-dot d2\"></span>\n              Strategic Target Goals & Expected Values\n            </div>\n            <div class=\"chart-wrap\" style=\"margin-bottom: 1.5rem;\">\n              <canvas id=\"goalsChart\" style=\"max-height: 250px; width: 100%;\"></canvas>\n            </div>\n\n            <div class=\"table-container\">\n              <table class=\"bk-table\">\n                <thead>\n                  <tr>\n                    <th>Objective</th>\n                    <th style=\"text-align: right;\">Target Amount</th>\n                    <th style=\"text-align: right;\">Projected FV</th>\n                    <th style=\"text-align: right;\">Surplus/Gap</th>\n                  </tr>\n                </thead>\n                <tbody id=\"analysis-goals-rows\">\n                  <tr>\n                    <td colspan=\"4\" class=\"text-center\" style=\"color: var(--text3); padding: 20px;\">No objectives modeled yet. Please switch on target planning.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- FULL SUMMARY COMMENTARY BLOCKS (NOW FULLY EDITABLE) -->\n        <div class=\"a-card\" id=\"executive-commentary-section\" style=\"margin-top: 1rem;\">\n          <div class=\"a-card-title\">\n            <span class=\"a-dot d3\"></span>\n            Professional Executive Commentary & Advice\n          </div>\n          \n          <!-- General Executive commentary (Interactive) -->\n          <div class=\"commentary-block\" style=\"margin-top: 0; padding-top: 0; border: none; margin-bottom: 1.5rem;\">\n            <label class=\"commentary-lbl\">\n              <i class=\"fa-solid fa-user-tie\"></i> Overall General Executive Summary Advice\n              <span class=\"commentary-char\" id=\"exec-comm-length\">0 / 1000 chars</span>\n            </label>\n            <textarea \n              id=\"exec-commentary-box\"\n              class=\"commentary-box\" \n              style=\"min-height: 120px; font-size: 13px;\"\n              maxlength=\"1000\" \n              placeholder=\"Provide general asset allocation recommendations, advisor assessments, risk profiles, or discretionary briefs here...\"\n              oninput=\"updateGlobalExecutiveCommentary(this.value)\"></textarea>\n            <div class=\"commentary-print\" id=\"exec-comm-print\">No general executive commentary entered.</div>\n          </div>\n\n          <div class=\"grp-label\" style=\"font-size: 10px; margin-bottom: 0.75rem; color: var(--text3);\">Tactical Strategy by Objective</div>\n          \n          <div id=\"executive-commentary-list\">\n            <!-- Render dynamic editable commentary cards from objectives here -->\n          </div>\n          <div class=\"wq-print-pdf-row\" style=\"display:flex; justify-content:flex-start; margin-top:12px;\">\n            <button type=\"button\" class=\"btn-pdf\" onclick=\"window.print()\">\n              <i class=\"fa-solid fa-print\"></i> Print As PDF\n            </button>\n          </div>\n        </div>\n\n      </div>\n    </main>\n\n  </div>\n\n  <script>\n    // In-memory state\n    let state = {\n      existingEnabled: false,\n      newGoalsEnabled: false,\n      existingInvestments: [\n        { id: 1, name: 'EPF Account 1', pv: 30000, pmt: 3600, startYear: 2021, currentYear: 2026, fv: 58000, cagr: 0 }\n      ],\n      newGoals: [\n        { id: 1, name: 'Retirement Wealth Nest', target: 500000, startYear: 2026, dueYear: 2046, pv: 25000, pmt: 6000, rate: 7.5, calculatedFv: 0, gap: 0, commentary: 'Targeting index trackers and high-yield trusts to secure 7.5% compound yield.', expanded: true }\n      ],\n      executiveCommentary: 'The proposed portfolio strategy aims to establish a highly resilient and diversified path to long-term wealth generation. Diversification across global indexes and selected debt instruments is advised to beat inflation benchmarks and protect purchasing power.'\n    };\n\n    // Charts references\n    let portfolioChartInst = null;\n    let goalsChartInst = null;\n\n    // Initialize state\n    window.onload = function() {\n      // Set defaults or load from localStorage if exists\n      const stored = localStorage.getItem('prosperflow_investment_state');\n      if (stored) {\n        try {\n          state = JSON.parse(stored);\n          // Sync toggles UI\n          document.getElementById('toggle-existing').checked = state.existingEnabled;\n          document.getElementById('toggle-new').checked = state.newGoalsEnabled;\n        } catch(e) {\n          console.error(\"Error parsing stored data\", e);\n        }\n      } else {\n        // First run defaults\n        state.existingEnabled = true;\n        state.newGoalsEnabled = true;\n        document.getElementById('toggle-existing').checked = true;\n        document.getElementById('toggle-new').checked = true;\n      }\n\n      // Initial layouts\n      toggleExistingContainer(false);\n      toggleNewContainer(false);\n      \n      // Render components\n      renderExistingTable();\n      renderAllGoals();\n      \n      // Set global commentary values\n      document.getElementById('exec-commentary-box').value = state.executiveCommentary || '';\n      document.getElementById('exec-comm-length').innerText = `${(state.executiveCommentary || '').length} / 1000 chars`;\n      document.getElementById('exec-comm-print').innerText = state.executiveCommentary || 'No general executive commentary entered.';\n\n      // Compute initial runs\n      calculateAllExistingCAGR(false);\n      calculateWACC(false);\n      calculateAllNewGoals(false);\n      \n      updateProgressBar();\n      updateAnalysisDashboard();\n    };\n\n    // Save State Utility\n    function saveState() {\n      localStorage.setItem('prosperflow_investment_state', JSON.stringify(state));\n    }\n\n    // Navigation Switching\n    function switchMainPage(pageId) {\n      document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));\n      document.querySelectorAll('.pill-btn').forEach(b => b.classList.remove('active'));\n      \n      document.getElementById(pageId).classList.add('active');\n      \n      // Find matching pill button\n      if (pageId === 'page-entry') {\n        document.querySelectorAll('.pill-btn')[0].classList.add('active');\n      } else {\n        document.querySelectorAll('.pill-btn')[1].classList.add('active');\n        // Redraw charts on tab change to ensure container dimensions are ready\n        setTimeout(renderCharts, 100);\n      }\n      \n      updateProgressBar();\n    }\n\n    function goToReportPage() {\n      switchMainPage('page-analysis');\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    }\n\n    function scrollToElement(id) {\n      const element = document.getElementById(id);\n      if (element) {\n        element.scrollIntoView({ behavior: 'smooth' });\n        // Set active state in sidebar\n        document.querySelectorAll('.sb-item').forEach(el => el.classList.remove('active'));\n        if (id === 'existing-inv-section') {\n          document.getElementById('sb-existing').classList.add('active');\n        } else {\n          document.getElementById('sb-planner').classList.add('active');\n        }\n      }\n    }\n\n    // Toggle Handlers\n    function toggleExistingContainer(shouldSave = true) {\n      const isChecked = document.getElementById('toggle-existing').checked;\n      state.existingEnabled = isChecked;\n      const el = document.getElementById('existing-inv-section');\n      if (isChecked) {\n        el.style.display = 'block';\n        document.getElementById('sb-existing').style.display = 'flex';\n      } else {\n        el.style.display = 'none';\n        document.getElementById('sb-existing').style.display = 'none';\n      }\n      if (shouldSave) {\n        saveState();\n        updateProgressBar();\n        updateAnalysisDashboard();\n      }\n    }\n\n    // Toggle Handlers\n    function toggleNewContainer(shouldSave = true) {\n      const isChecked = document.getElementById('toggle-new').checked;\n      state.newGoalsEnabled = isChecked;\n      const el = document.getElementById('new-inv-section');\n      if (isChecked) {\n        el.style.display = 'block';\n        document.getElementById('sb-planner').style.display = 'flex';\n      } else {\n        el.style.display = 'none';\n        document.getElementById('sb-planner').style.display = 'none';\n      }\n      if (shouldSave) {\n        saveState();\n        updateProgressBar();\n        updateAnalysisDashboard();\n      }\n    }\n\n    // Collapsible Matrix Card Trigger\n    function toggleCardBody(headerEl) {\n      headerEl.classList.toggle('open');\n      const chev = headerEl.querySelector('.chev');\n      if (chev) chev.classList.toggle('open');\n      const body = headerEl.nextElementSibling;\n      if (body) body.classList.toggle('open');\n    }\n\n    // Reset Strategy\n    function resetAllFormData() {\n      if (confirm('Are you sure you want to restore default entries? This action cannot be undone.')) {\n        localStorage.removeItem('prosperflow_investment_state');\n        state = {\n          existingEnabled: true,\n          newGoalsEnabled: true,\n          existingInvestments: [\n            { id: Date.now(), name: 'EPF Account 1', pv: 30000, pmt: 3600, startYear: 2021, currentYear: 2026, fv: 58000, cagr: 0 }\n          ],\n          newGoals: [\n            { id: Date.now() + 1, name: 'Retirement Wealth Nest', target: 500000, startYear: 2026, dueYear: 2046, pv: 25000, pmt: 6000, rate: 7.5, calculatedFv: 0, gap: 0, commentary: 'Targeting index trackers and high-yield trusts to secure 7.5% compound yield.', expanded: true }\n          ],\n          executiveCommentary: 'The proposed portfolio strategy aims to establish a highly resilient and diversified path to long-term wealth generation. Diversification across global indexes and selected debt instruments is advised to beat inflation benchmarks and protect purchasing power.'\n        };\n        \n        document.getElementById('toggle-existing').checked = true;\n        document.getElementById('toggle-new').checked = true;\n        \n        // Update general commentary text inputs\n        document.getElementById('exec-commentary-box').value = state.executiveCommentary;\n        document.getElementById('exec-comm-length').innerText = `${state.executiveCommentary.length} / 1000 chars`;\n        document.getElementById('exec-comm-print').innerText = state.executiveCommentary;\n\n        toggleExistingContainer(false);\n        toggleNewContainer(false);\n        renderExistingTable();\n        renderAllGoals();\n        calculateAllExistingCAGR(true);\n        calculateWACC(true);\n        calculateAllNewGoals(true);\n        updateProgressBar();\n        updateAnalysisDashboard();\n      }\n    }\n\n    // \u2500\u2500 BISECTION RATE SOLVER FOR CAGR (Financial Rate Calculator) \u2500\u2500\n    // Finds 'r' where PV*(1+r)^N + PMT*((1+r)^N - 1)/r = FV\n    function solveCAGR(pv, fv, pmt, n) {\n      if (n <= 0) return 0;\n      if (pv <= 0 && pmt <= 0) return 0;\n\n      let low = -0.95; // Limit return loss to -95%\n      let high = 5.0;  // Limit return top to 500%\n      let mid = 0;\n      \n      function calcFV(r) {\n        if (Math.abs(r) < 1e-6) {\n          return pv + pmt * n;\n        }\n        return pv * Math.pow(1 + r, n) + pmt * (Math.pow(1 + r, n) - 1) / r;\n      }\n      \n      // Adjust boundary thresholds\n      let f_low = calcFV(low) - fv;\n      let f_high = calcFV(high) - fv;\n      if (f_low * f_high > 0) {\n        if (f_low > 0) {\n          low = -0.9999;\n        } else {\n          high = 50.0; // Extend to 5000% if astronomical returns\n        }\n      }\n      \n      for (let i = 0; i < 120; i++) {\n        mid = (low + high) / 2;\n        let f_mid = calcFV(mid) - fv;\n        if (Math.abs(f_mid) < 1e-6) {\n          return mid;\n        }\n        if ((calcFV(low) - fv) * f_mid < 0) {\n          high = mid;\n        } else {\n          low = mid;\n        }\n      }\n      return mid;\n    }\n\n    // \u2500\u2500 PORTFOLIO SEGMENT: EXISTING PORTFOLIO RENDER \u2500\u2500\n    function renderExistingTable() {\n      const tbody = document.getElementById('existing-tbody');\n      tbody.innerHTML = '';\n\n      if (state.existingInvestments.length === 0) {\n        tbody.innerHTML = `\n          <tr>\n            <td colspan=\"9\" class=\"text-center\" style=\"padding: 24px; color: var(--text3);\">\n              No assets configured. Click \"Add New Investment Position\" below to start.\n            </td>\n          </tr>\n        `;\n        document.getElementById('total-existing-val-header').innerText = 'RM 0.00 Total';\n        return;\n      }\n\n      state.existingInvestments.forEach((inv, idx) => {\n        const tr = document.createElement('tr');\n        tr.innerHTML = `\n          <td class=\"bold mono\">${idx + 1}</td>\n          <td>\n            <input type=\"text\" class=\"inp-t\" value=\"${inv.name}\" placeholder=\"e.g. Bluechip Equity Fund\" onchange=\"updateExistingField(${inv.id}, 'name', this.value)\">\n          </td>\n          <td>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" class=\"inp pl\" value=\"${inv.pv}\" step=\"1000\" onchange=\"updateExistingField(${inv.id}, 'pv', parseFloat(this.value))\">\n            </div>\n          </td>\n          <td>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" class=\"inp pl\" value=\"${inv.pmt}\" step=\"100\" onchange=\"updateExistingField(${inv.id}, 'pmt', parseFloat(this.value))\">\n            </div>\n          </td>\n          <td>\n            <input type=\"number\" class=\"inp text-center\" value=\"${inv.startYear}\" step=\"1\" onchange=\"updateExistingField(${inv.id}, 'startYear', parseInt(this.value))\">\n          </td>\n          <td>\n            <input type=\"number\" class=\"inp text-center\" value=\"${inv.currentYear}\" step=\"1\" onchange=\"updateExistingField(${inv.id}, 'currentYear', parseInt(this.value))\">\n          </td>\n          <td>\n            <div class=\"pfx-wrap\">\n              <span class=\"pfx\">RM</span>\n              <input type=\"number\" class=\"inp pl\" value=\"${inv.fv}\" step=\"1000\" onchange=\"updateExistingField(${inv.id}, 'fv', parseFloat(this.value))\">\n            </div>\n          </td>\n          <td class=\"text-right bold mono\" id=\"cagr-val-${inv.id}\" style=\"font-size: 13px;\">\n            ${(inv.cagr * 100).toFixed(2)}%\n          </td>\n          <td>\n            <button class=\"btn-rm\" onclick=\"removeExistingRow(${inv.id})\" title=\"Remove position\">\n              <i class=\"fa-solid fa-trash-can\"></i>\n            </button>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n\n      calculateHeaderTotal();\n    }\n\n    function addExistingRow() {\n      const currentYear = new Date().getFullYear();\n      const newPos = {\n        id: Date.now(),\n        name: `Asset Matrix Position ${state.existingInvestments.length + 1}`,\n        pv: 5000,\n        pmt: 500,\n        startYear: currentYear - 3,\n        currentYear: currentYear,\n        fv: 8000,\n        cagr: 0\n      };\n      state.existingInvestments.push(newPos);\n      saveState();\n      renderExistingTable();\n      calculateAllExistingCAGR();\n      updateProgressBar();\n    }\n\n    function removeExistingRow(id) {\n      state.existingInvestments = state.existingInvestments.filter(item => item.id !== id);\n      saveState();\n      renderExistingTable();\n      calculateAllExistingCAGR();\n      calculateWACC();\n      updateProgressBar();\n    }\n\n    function updateExistingField(id, field, value) {\n      const item = state.existingInvestments.find(x => x.id === id);\n      if (item) {\n        if (field === 'name') {\n          item[field] = value;\n        } else {\n          item[field] = isNaN(value) ? 0 : value;\n        }\n        \n        // Auto recalibrate individual CAGR when values change\n        const yearsDiff = item.currentYear - item.startYear;\n        item.cagr = solveCAGR(item.pv, item.fv, item.pmt, yearsDiff);\n        \n        const cagrCell = document.getElementById(`cagr-val-${item.id}`);\n        if (cagrCell) {\n          cagrCell.innerText = `${(item.cagr * 100).toFixed(2)}%`;\n        }\n        \n        calculateHeaderTotal();\n        saveState();\n        updateProgressBar();\n      }\n    }\n\n    function calculateHeaderTotal() {\n      const total = state.existingInvestments.reduce((sum, item) => sum + (item.fv || 0), 0);\n      document.getElementById('total-existing-val-header').innerText = `${formatCurrency(total)} Total`;\n      document.getElementById('side-total-existing').innerText = formatCurrency(total);\n    }\n\n    function calculateAllExistingCAGR(shouldSave = true) {\n      state.existingInvestments.forEach(item => {\n        const yearsDiff = item.currentYear - item.startYear;\n        item.cagr = solveCAGR(item.pv, item.fv, item.pmt, yearsDiff);\n      });\n      if (shouldSave) {\n        saveState();\n        updateAnalysisDashboard();\n      }\n    }\n\n    // WACC Calculation Event\n    function calculateWACC(shouldSave = true) {\n      const totalMV = state.existingInvestments.reduce((sum, item) => sum + (item.fv || 0), 0);\n      const summaryTbody = document.getElementById('wacc-summary-tbody');\n      \n      if (totalMV === 0 || state.existingInvestments.length === 0) {\n        document.getElementById('wacc-panel').style.display = 'none';\n        document.getElementById('side-wacc-val').innerText = \"0.00%\";\n        return;\n      }\n\n      summaryTbody.innerHTML = '';\n      let runningWACC = 0;\n\n      state.existingInvestments.forEach((item, index) => {\n        const weight = item.fv / totalMV;\n        const weightedCont = item.cagr * weight;\n        runningWACC += weightedCont;\n\n        const tr = document.createElement('tr');\n        tr.innerHTML = `\n          <td class=\"bold mono\">${index + 1}</td>\n          <td class=\"bold\">${item.name}</td>\n          <td class=\"text-right mono\">${formatCurrency(item.fv)}</td>\n          <td class=\"text-right mono\">${(item.cagr * 100).toFixed(2)}%</td>\n          <td class=\"text-right mono\">${(weight * 100).toFixed(1)}%</td>\n          <td class=\"text-right mono bold\" style=\"color: var(--blue)\">${(weightedCont * 100).toFixed(2)}%</td>\n        `;\n        summaryTbody.appendChild(tr);\n      });\n\n      // Update summaries\n      document.getElementById('summary-total-mv').innerText = formatCurrency(totalMV);\n      document.getElementById('summary-wacc-val').innerText = `${(runningWACC * 100).toFixed(2)}%`;\n      document.getElementById('side-wacc-val').innerText = `${(runningWACC * 100).toFixed(2)}%`;\n\n      // Compare to Inflation rate\n      const inflation = parseFloat(document.getElementById('inflation-rate').value) || 3.0;\n      const margin = (runningWACC * 100) - inflation;\n      const marginBadge = document.getElementById('summary-benchmark-val');\n      const sideMarginBadge = document.getElementById('side-inflation-margin');\n      \n      const comparisonText = `${margin >= 0 ? 'Beating' : 'Trailing'} by ${Math.abs(margin).toFixed(2)}%`;\n      marginBadge.innerText = comparisonText;\n      sideMarginBadge.innerText = `${margin >= 0 ? '+' : ''}${margin.toFixed(2)}%`;\n\n      if (margin >= 0) {\n        marginBadge.className = \"wacc-val positive\";\n        document.getElementById('summary-benchmark-card').style.borderLeftColor = \"var(--green)\";\n        sideMarginBadge.className = \"ss-v ss-b positive\";\n      } else {\n        marginBadge.className = \"wacc-val negative\";\n        document.getElementById('summary-benchmark-card').style.borderLeftColor = \"var(--red)\";\n        sideMarginBadge.className = \"ss-v ss-b negative\";\n      }\n\n      document.getElementById('wacc-panel').style.display = 'block';\n      \n      if (shouldSave) {\n        saveState();\n        updateProgressBar();\n        updateAnalysisDashboard();\n      }\n    }\n\n\n    // \u2500\u2500 PLANNER SECTION: GOALS Accumulator \u2500\u2500\n    function renderAllGoals() {\n      const container = document.getElementById('new-goals-container');\n      container.innerHTML = '';\n\n      if (state.newGoals.length === 0) {\n        container.innerHTML = `\n          <div class=\"empty-state\">\n            <i class=\"fa-solid fa-compass-drafting\" style=\"font-size: 32px; margin-bottom: 12px; display: block;\"></i>\n            No active growth targets modeled. Click the button below to model your first target return objective.\n          </div>\n        `;\n        document.getElementById('side-goals-count').innerText = \"0\";\n        return;\n      }\n\n      document.getElementById('side-goals-count').innerText = state.newGoals.length;\n\n      state.newGoals.forEach((goal, index) => {\n        const isExpanded = goal.expanded !== false;\n        const card = document.createElement('div');\n        card.className = \"card\";\n        card.innerHTML = `\n          <div class=\"ch ${isExpanded ? 'open' : ''}\" onclick=\"toggleGoalCardUI(${goal.id})\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci2\"><i class=\"fa-solid fa-bullseye\"></i></div>\n              <div>\n                <div class=\"ch-title bold\">${goal.name || 'Objective Matrix Target'}</div>\n                <div class=\"ch-sub\">Period: ${goal.dueYear - goal.startYear} Years | Aim: ${formatCurrency(goal.target)}</div>\n              </div>\n            </div>\n            <div class=\"ch-right\">\n              <span class=\"ch-sum\" id=\"goal-header-summary-${goal.id}\">\n                Projected: ${formatCurrency(goal.calculatedFv || 0)}\n              </span>\n              <i class=\"fa-solid fa-chevron-down chev ${isExpanded ? 'open' : ''}\"></i>\n            </div>\n          </div>\n\n          <div class=\"cb ${isExpanded ? 'open' : ''}\">\n            <div style=\"display: grid; grid-template-columns: 2fr 1fr; gap: 1.5rem; flex-wrap: wrap;\">\n              \n              <!-- Core Inputs -->\n              <div class=\"flex flex-col gap-3\">\n                <div class=\"f-static\">\n                  <div>\n                    <span class=\"f-label\">Investment Objective Name</span>\n                    <div class=\"f-sub\">Give this strategy or financial goal a distinct name.</div>\n                  </div>\n                  <input type=\"text\" class=\"inp-t\" style=\"text-align: right;\" value=\"${goal.name}\" onchange=\"updateGoalField(${goal.id}, 'name', this.value)\">\n                </div>\n\n                <div class=\"f-static\">\n                  <div>\n                    <span class=\"f-label\">Target Funding Goal</span>\n                    <div class=\"f-sub\">What aggregate value do you need to accumulate?</div>\n                  </div>\n                  <div class=\"pfx-wrap\">\n                    <span class=\"pfx\">RM</span>\n                    <input type=\"number\" class=\"inp pl\" value=\"${goal.target}\" step=\"1000\" onchange=\"updateGoalField(${goal.id}, 'target', parseFloat(this.value))\">\n                  </div>\n                </div>\n\n                <div class=\"grid-2\" style=\"width: 100%; grid-column: span 2; border-bottom: 1px solid var(--border); padding-bottom: 10px;\">\n                  <div class=\"f-static\" style=\"grid-template-columns: 100px 1fr; border-bottom: none;\">\n                    <span class=\"f-label\">Start Year</span>\n                    <input type=\"number\" class=\"inp\" value=\"${goal.startYear}\" step=\"1\" onchange=\"updateGoalField(${goal.id}, 'startYear', parseInt(this.value))\">\n                  </div>\n                  <div class=\"f-static\" style=\"grid-template-columns: 100px 1fr; border-bottom: none;\">\n                    <span class=\"f-label\">Due Year</span>\n                    <input type=\"number\" class=\"inp\" value=\"${goal.dueYear}\" step=\"1\" onchange=\"updateGoalField(${goal.id}, 'dueYear', parseInt(this.value))\">\n                  </div>\n                </div>\n\n                <div class=\"f-static\">\n                  <div>\n                    <span class=\"f-label\">Initial Capital Outlay (PV)</span>\n                    <div class=\"f-sub\">Your immediate starting seed contribution.</div>\n                  </div>\n                  <div class=\"pfx-wrap\">\n                    <span class=\"pfx\">RM</span>\n                    <input type=\"number\" class=\"inp pl\" value=\"${goal.pv}\" step=\"1000\" onchange=\"updateGoalField(${goal.id}, 'pv', parseFloat(this.value))\">\n                  </div>\n                </div>\n\n                <div class=\"f-static\">\n                  <div>\n                    <span class=\"f-label\">Annual Recurrent Deposit (PMT)</span>\n                    <div class=\"f-sub\">Additional capital committed at year-ends.</div>\n                  </div>\n                  <div class=\"pfx-wrap\">\n                    <span class=\"pfx\">RM</span>\n                    <input type=\"number\" class=\"inp pl\" value=\"${goal.pmt}\" step=\"100\" onchange=\"updateGoalField(${goal.id}, 'pmt', parseFloat(this.value))\">\n                  </div>\n                </div>\n\n                <div class=\"f-static\">\n                  <div>\n                    <span class=\"f-label\">Expected Growth Yield (Annual Rate)</span>\n                    <div class=\"f-sub\">The projected rate of return on invested funds.</div>\n                  </div>\n                  <div class=\"pfx-wrap\">\n                    <input type=\"number\" class=\"inp\" value=\"${goal.rate}\" step=\"0.1\" style=\"padding-right: 20px;\" onchange=\"updateGoalField(${goal.id}, 'rate', parseFloat(this.value))\">\n                    <span style=\"position: absolute; right: 10px; top: 50%; transform: translateY(-50%); font-size: 11px; color: var(--text3);\">%</span>\n                  </div>\n                </div>\n              </div>\n\n              <!-- Quick Results Block & Gauge -->\n              <div style=\"background: var(--surface2); padding: 16px; border-radius: var(--rl); display: flex; flex-direction: column; justify-content: space-between; border: 1px solid var(--border);\">\n                <div>\n                  <div class=\"tot-label\">FORMULATED FUTURE VALUE PROJECTION</div>\n                  <div class=\"tot-val\" id=\"goal-fv-calc-${goal.id}\" style=\"font-size: 26px; color: var(--blue); margin-top: 5px;\">\n                    ${formatCurrency(goal.calculatedFv || 0)}\n                  </div>\n                  \n                  <div class=\"ss-div\" style=\"margin: 15px 0;\"></div>\n\n                  <div class=\"tot-label\">FUNDING TARGET STATUS</div>\n                  <div id=\"goal-status-${goal.id}\" style=\"margin-top: 5px;\">\n                    <!-- Gap analysis output -->\n                  </div>\n                </div>\n\n                <div style=\"margin-top: 20px;\">\n                  <button class=\"btn-nav btn-pri\" style=\"width: 100%; justify-content: center;\" onclick=\"triggerGoalCalculation(${goal.id})\">\n                    <i class=\"fa-solid fa-calculator\"></i> Calculate Investment\n                  </button>\n                  <button class=\"btn-rm\" style=\"width: 100%; margin-top: 8px; border-style: solid;\" onclick=\"removeGoalCard(${goal.id})\">\n                    <i class=\"fa-solid fa-trash-can\"></i> Discard Objective\n                  </button>\n                </div>\n              </div>\n\n            </div>\n\n            <!-- Dedicated Commentary Box for target planning card -->\n            <div class=\"commentary-block\">\n              <label class=\"commentary-lbl\">\n                <i class=\"fa-solid fa-feather-pointed\"></i> Commentary & Tactical Plan for ${goal.name || 'this goal'}\n                <span class=\"commentary-char\" id=\"comm-length-${goal.id}\">0 / 400 chars</span>\n              </label>\n              <textarea \n                class=\"commentary-box\" \n                maxlength=\"400\" \n                placeholder=\"Detail tactical assumptions here (e.g. 'Targeting index trackers to secure 7.5% compound yield...')\"\n                oninput=\"updateGoalCommentary(${goal.id}, this.value)\">${goal.commentary || ''}</textarea>\n              <div class=\"commentary-print\" id=\"comm-print-${goal.id}\">${goal.commentary || 'No advisory commentary provided for this specific objective.'}</div>\n            </div>\n\n          </div>\n        `;\n        container.appendChild(card);\n        updateGoalStatusUI(goal);\n      });\n    }\n\n    function toggleGoalCardUI(id) {\n      const goal = state.newGoals.find(g => g.id === id);\n      if (goal) {\n        goal.expanded = !(goal.expanded !== false);\n        saveState();\n        renderAllGoals();\n      }\n    }\n\n    function addNewGoalCard() {\n      const currentYear = new Date().getFullYear();\n      const newG = {\n        id: Date.now(),\n        name: `Portfolio Growth Target ${state.newGoals.length + 1}`,\n        target: 100000,\n        startYear: currentYear,\n        dueYear: currentYear + 15,\n        pv: 10000,\n        pmt: 2400,\n        rate: 6.5,\n        calculatedFv: 0,\n        gap: 0,\n        commentary: '',\n        expanded: true\n      };\n      state.newGoals.push(newG);\n      saveState();\n      renderAllGoals();\n      triggerGoalCalculation(newG.id);\n      updateProgressBar();\n    }\n\n    function removeGoalCard(id) {\n      state.newGoals = state.newGoals.filter(g => g.id !== id);\n      saveState();\n      renderAllGoals();\n      updateProgressBar();\n      updateAnalysisDashboard();\n    }\n\n    function updateGoalField(id, field, value) {\n      const goal = state.newGoals.find(g => g.id === id);\n      if (goal) {\n        if (field === 'name') {\n          goal[field] = value;\n        } else {\n          goal[field] = isNaN(value) ? 0 : value;\n        }\n        saveState();\n      }\n    }\n\n    // Dynamic update from Planner view \u2014 synchronizes with Report tab immediately\n    function updateGoalCommentary(id, text) {\n      const goal = state.newGoals.find(g => g.id === id);\n      if (goal) {\n        goal.commentary = text;\n        const count = document.getElementById(`comm-length-${id}`);\n        if (count) count.innerText = `${text.length} / 400 chars`;\n        const pr = document.getElementById(`comm-print-${id}`);\n        if (pr) pr.innerText = text || 'No advisory commentary provided for this specific objective.';\n        \n        // Synchronize with report tab text fields\n        const repTextArea = document.querySelector(`#executive-commentary-list textarea[oninput*=\"updateGoalCommentaryFromReport(${id}\"]`);\n        if (repTextArea) {\n          repTextArea.value = text;\n        }\n        const repLength = document.getElementById(`rep-comm-length-${id}`);\n        if (repLength) {\n          repLength.innerText = `${text.length} / 400 chars`;\n        }\n        const repPrint = document.getElementById(`rep-comm-print-${id}`);\n        if (repPrint) {\n          repPrint.innerText = text || 'No specific objective tactical commentary provided.';\n        }\n        \n        saveState();\n      }\n    }\n\n    // Dynamic update from Report view \u2014 synchronizes with Planner tab immediately\n    function updateGoalCommentaryFromReport(id, text) {\n      const goal = state.newGoals.find(g => g.id === id);\n      if (goal) {\n        goal.commentary = text;\n        \n        // Sync back with the Planner view text elements\n        const plannerTextAreas = document.querySelectorAll(`textarea[oninput*=\"updateGoalCommentary(${id}\"]`);\n        plannerTextAreas.forEach(ta => {\n          ta.value = text;\n        });\n        const plannerCharCount = document.getElementById(`comm-length-${id}`);\n        if (plannerCharCount) {\n          plannerCharCount.innerText = `${text.length} / 400 chars`;\n        }\n        const plannerPrint = document.getElementById(`comm-print-${id}`);\n        if (plannerPrint) {\n          plannerPrint.innerText = text || 'No advisory commentary provided for this specific objective.';\n        }\n\n        // Sync report-specific length & print previews\n        const repLength = document.getElementById(`rep-comm-length-${id}`);\n        if (repLength) {\n          repLength.innerText = `${text.length} / 400 chars`;\n        }\n        const repPrint = document.getElementById(`rep-comm-print-${id}`);\n        if (repPrint) {\n          repPrint.innerText = text || 'No specific objective tactical commentary provided.';\n        }\n        \n        saveState();\n      }\n    }\n\n    // General overall commentary updates\n    function updateGlobalExecutiveCommentary(text) {\n      state.executiveCommentary = text;\n      const count = document.getElementById('exec-comm-length');\n      if (count) count.innerText = `${text.length} / 1000 chars`;\n      const pr = document.getElementById('exec-comm-print');\n      if (pr) pr.innerText = text || 'No general executive commentary entered.';\n      saveState();\n    }\n\n    // Compounding solver for expected Future Value\n    function triggerGoalCalculation(id) {\n      const goal = state.newGoals.find(g => g.id === id);\n      if (goal) {\n        const r = goal.rate / 100;\n        const n = goal.dueYear - goal.startYear;\n        const pv = goal.pv;\n        const pmt = goal.pmt;\n\n        let fv = 0;\n        if (n <= 0) {\n          fv = pv;\n        } else {\n          if (Math.abs(r) < 1e-6) {\n            fv = pv + pmt * n;\n          } else {\n            // Standard Compounding formulation: PV*(1+r)^N + PMT*(((1+r)^N - 1)/r)\n            fv = pv * Math.pow(1 + r, n) + pmt * (Math.pow(1 + r, n) - 1) / r;\n          }\n        }\n\n        goal.calculatedFv = fv;\n        goal.gap = fv - goal.target;\n\n        saveState();\n        \n        // Update direct subcomponents\n        const fvDisplay = document.getElementById(`goal-fv-calc-${id}`);\n        if (fvDisplay) fvDisplay.innerText = formatCurrency(fv);\n        \n        const headerSummary = document.getElementById(`goal-header-summary-${id}`);\n        if (headerSummary) headerSummary.innerText = `Projected: ${formatCurrency(fv)}`;\n\n        updateGoalStatusUI(goal);\n        updateProgressBar();\n        updateAnalysisDashboard();\n      }\n    }\n\n    function calculateAllNewGoals(shouldSave = true) {\n      state.newGoals.forEach(g => {\n        const r = g.rate / 100;\n        const n = g.dueYear - g.startYear;\n        const pv = g.pv;\n        const pmt = g.pmt;\n        let fv = 0;\n        if (n <= 0) {\n          fv = pv;\n        } else {\n          if (Math.abs(r) < 1e-6) {\n            fv = pv + pmt * n;\n          } else {\n            fv = pv * Math.pow(1 + r, n) + pmt * (Math.pow(1 + r, n) - 1) / r;\n          }\n        }\n        g.calculatedFv = fv;\n        g.gap = fv - g.target;\n      });\n      if (shouldSave) saveState();\n    }\n\n    function updateGoalStatusUI(goal) {\n      const statusBox = document.getElementById(`goal-status-${goal.id}`);\n      if (!statusBox) return;\n\n      const gap = goal.gap || 0;\n      if (gap >= 0) {\n        statusBox.innerHTML = `\n          <div class=\"positive bold\" style=\"font-size: 14px;\">\n            <i class=\"fa-solid fa-circle-check\"></i> Surplus of ${formatCurrency(gap)}\n          </div>\n          <p style=\"font-size: 11px; color: var(--text3); margin-top: 4px;\">Excellent progress. Model is fully capitalized to surpass standard objectives.</p>\n        `;\n      } else {\n        statusBox.innerHTML = `\n          <div class=\"negative bold\" style=\"font-size: 14px;\">\n            <i class=\"fa-solid fa-circle-exclamation\"></i> Deficit of ${formatCurrency(Math.abs(gap))}\n          </div>\n          <p style=\"font-size: 11px; color: var(--text3); margin-top: 4px;\">Model reveals capital shortage. Consider increasing recurring deposits, start year, or yield target.</p>\n        `;\n      }\n    }\n\n\n    // \u2500\u2500 GENERAL WORKSPACE UTILITY: PROGRESS TRACKER \u2500\u2500\n    function updateProgressBar() {\n      let progressCount = 0;\n      let totalSteps = 2; // Basic setup sections\n\n      if (state.existingEnabled) {\n        totalSteps += 1;\n        // Verify if at least one position holds capital\n        const hasPositions = state.existingInvestments.length > 0;\n        if (hasPositions) progressCount += 1;\n      }\n      \n      if (state.newGoalsEnabled) {\n        totalSteps += 1;\n        const hasGoals = state.newGoals.length > 0;\n        if (hasGoals) progressCount += 1;\n      }\n\n      // Check toggles themselves\n      if (state.existingEnabled) progressCount += 1;\n      if (state.newGoalsEnabled) progressCount += 1;\n\n      const pct = Math.min(100, Math.round((progressCount / totalSteps) * 100));\n      const pBar = document.getElementById('prog-bar');\n      const pPct = document.getElementById('prog-pct');\n      \n      if (pBar) pBar.style.width = `${pct}%`;\n      if (pPct) pPct.innerText = `${pct}%`;\n    }\n\n    // \u2500\u2500 CORE ADVISORY REPORT & METRIC SYNC \u2500\u2500\n    function updateAnalysisDashboard() {\n      // 1. Matrices\n      const totalCurrentAssets = state.existingEnabled \n        ? state.existingInvestments.reduce((sum, item) => sum + (item.fv || 0), 0)\n        : 0;\n      \n      document.getElementById('mx-current-assets').innerText = formatCurrency(totalCurrentAssets);\n      document.getElementById('mx-assets-count').innerText = `${state.existingInvestments.length} Active Positions`;\n\n      // Return WACC\n      let portfolioWACC = 0;\n      if (state.existingEnabled && totalCurrentAssets > 0) {\n        state.existingInvestments.forEach(item => {\n          const weight = item.fv / totalCurrentAssets;\n          portfolioWACC += item.cagr * weight;\n        });\n      }\n      document.getElementById('mx-portfolio-return').innerText = `${(portfolioWACC * 100).toFixed(2)}%`;\n\n      const inflation = parseFloat(document.getElementById('inflation-rate').value) || 3.0;\n      const beat = (portfolioWACC * 100) - inflation;\n      document.getElementById('mx-wacc-comparison').innerText = totalCurrentAssets > 0 \n        ? `${beat >= 0 ? 'Beats' : 'Misses'} inflation by ${Math.abs(beat).toFixed(2)}%`\n        : 'Portfolio empty';\n\n      // Goals planned metrics\n      const totalGoalsTarget = state.newGoalsEnabled\n        ? state.newGoals.reduce((sum, item) => sum + (item.target || 0), 0)\n        : 0;\n      const totalGoalsProjected = state.newGoalsEnabled\n        ? state.newGoals.reduce((sum, item) => sum + (item.calculatedFv || 0), 0)\n        : 0;\n\n      document.getElementById('mx-planned-fv').innerText = formatCurrency(totalGoalsProjected);\n      document.getElementById('mx-goals-total').innerText = `${state.newGoals.length} Defined Objectives`;\n\n      const gapProgress = totalGoalsTarget > 0 \n        ? Math.min(100, Math.round((totalGoalsProjected / totalGoalsTarget) * 100))\n        : 0;\n      \n      document.getElementById('mx-accomplish-rate').innerText = `${gapProgress}%`;\n      document.getElementById('mx-funding-status').innerText = totalGoalsTarget > 0 \n        ? `Agg. Target: ${formatCurrency(totalGoalsTarget)}`\n        : 'No target targets';\n\n      // 2. Report Lists Tables\n      syncAnalysisReportTables(totalCurrentAssets, portfolioWACC);\n    }\n\n    function syncAnalysisReportTables(totalCurrentAssets, portfolioWACC) {\n      // Portfolio Allocation Matrix Table\n      const pBody = document.getElementById('analysis-portfolio-rows');\n      pBody.innerHTML = '';\n\n      if (!state.existingEnabled || state.existingInvestments.length === 0) {\n        pBody.innerHTML = `\n          <tr>\n            <td colspan=\"4\" class=\"text-center\" style=\"color: var(--text3); padding: 20px;\">\n              Portfolio disabled or empty. Construct asset list in Planner tab.\n            </td>\n          </tr>\n        `;\n      } else {\n        state.existingInvestments.forEach(item => {\n          const weight = item.fv / totalCurrentAssets;\n          const tr = document.createElement('tr');\n          tr.innerHTML = `\n            <td>\n              <div class=\"cat-badge\">\n                <span class=\"cat-dot\" style=\"background: var(--blue);\"></span>\n                <span class=\"bold\">${item.name}</span>\n              </div>\n            </td>\n            <td style=\"text-align: right;\" class=\"mono\">${formatCurrency(item.fv)}</td>\n            <td style=\"text-align: right;\" class=\"mono\">${(item.cagr * 100).toFixed(2)}%</td>\n            <td style=\"text-align: right;\" class=\"mono\">${(weight * 100).toFixed(1)}%</td>\n          `;\n          pBody.appendChild(tr);\n        });\n      }\n\n      // Goals Target Table\n      const gBody = document.getElementById('analysis-goals-rows');\n      gBody.innerHTML = '';\n\n      if (!state.newGoalsEnabled || state.newGoals.length === 0) {\n        gBody.innerHTML = `\n          <tr>\n            <td colspan=\"4\" class=\"text-center\" style=\"color: var(--text3); padding: 20px;\">\n              Planning disabled or empty. Construct objectives in Planner tab.\n            </td>\n          </tr>\n        `;\n      } else {\n        state.newGoals.forEach(g => {\n          const tr = document.createElement('tr');\n          const isSurplus = g.gap >= 0;\n          tr.innerHTML = `\n            <td>\n              <div class=\"cat-badge\">\n                <span class=\"cat-dot\" style=\"background: ${isSurplus ? 'var(--green)' : 'var(--amber)'};\"></span>\n                <span class=\"bold\">${g.name}</span>\n              </div>\n            </td>\n            <td style=\"text-align: right;\" class=\"mono\">${formatCurrency(g.target)}</td>\n            <td style=\"text-align: right;\" class=\"mono\" style=\"color: var(--blue);\">${formatCurrency(g.calculatedFv)}</td>\n            <td style=\"text-align: right;\" class=\"mono bold ${isSurplus ? 'positive' : 'negative'}\">\n              ${isSurplus ? '+' : ''}${formatCurrency(g.gap)}\n            </td>\n          `;\n          gBody.appendChild(tr);\n        });\n      }\n\n      // 3. Sync Dynamic Printable Commentary Box List (All Editable)\n      syncExecutiveCommentaryReport();\n    }\n\n    function syncExecutiveCommentaryReport() {\n      const commContainer = document.getElementById('executive-commentary-list');\n      commContainer.innerHTML = '';\n      \n      let commentsAdded = 0;\n\n      if (state.newGoalsEnabled) {\n        state.newGoals.forEach(g => {\n          commentsAdded++;\n          const div = document.createElement('div');\n          div.className = \"ss-body\";\n          div.style.marginBottom = \"15px\";\n          div.style.border = \"1px solid var(--border)\";\n          div.style.borderRadius = \"var(--r)\";\n          div.style.background = \"var(--surface)\";\n          div.style.padding = \"12px 14px\";\n          div.innerHTML = `\n            <div style=\"font-weight: 500; font-size: 11px; text-transform: uppercase; color: var(--text2); margin-bottom: 6px; display: flex; justify-content: space-between; align-items: center;\">\n              <span>Objective Focus: ${g.name}</span>\n              <span style=\"font-weight: normal; text-transform: none; color: var(--text3);\" id=\"rep-comm-length-${g.id}\">${(g.commentary || '').length} / 400 chars</span>\n            </div>\n            <textarea \n              class=\"commentary-box\" \n              maxlength=\"400\" \n              placeholder=\"Detail tactical strategic assumptions here...\"\n              style=\"min-height: 70px; font-size: 13px; line-height: 1.5; background: var(--surface2);\"\n              oninput=\"updateGoalCommentaryFromReport(${g.id}, this.value)\">${g.commentary || ''}</textarea>\n            <div class=\"commentary-print\" style=\"margin-top: 5px; font-size: 13px; font-style: italic; color: var(--text2);\" id=\"rep-comm-print-${g.id}\">${g.commentary || 'No specific objective tactical commentary provided.'}</div>\n          `;\n          commContainer.appendChild(div);\n        });\n      }\n\n      if (commentsAdded === 0) {\n        commContainer.innerHTML = `\n          <div style=\"font-size: 12px; color: var(--text3); font-style: italic; padding: 10px 0;\">\n            No custom target planning models active. Turn on target planning to edit specific objective briefs.\n          </div>\n        `;\n      }\n    }\n\n\n    // \u2500\u2500 CHARTING PREPARATION AND RENDER \u2500\u2500\n    function renderCharts() {\n      // Ensure canvas element is ready\n      const pCanvas = document.getElementById('portfolioChart');\n      const gCanvas = document.getElementById('goalsChart');\n      if (!pCanvas || !gCanvas) return;\n\n      // Destroy previous instances\n      if (portfolioChartInst) portfolioChartInst.destroy();\n      if (goalsChartInst) goalsChartInst.destroy();\n\n      // Chart 1: Portfolio Allocation Donut\n      const validAssets = state.existingEnabled ? state.existingInvestments.filter(item => item.fv > 0) : [];\n      if (validAssets.length === 0) {\n        // Render simple fallback label\n        const ctx = pCanvas.getContext('2d');\n        ctx.clearRect(0,0,250,250);\n        ctx.fillStyle = '#a09d98';\n        ctx.font = '12px DM Sans';\n        ctx.textAlign = 'center';\n        ctx.fillText('No portfolio holdings mapped.', 125, 125);\n      } else {\n        portfolioChartInst = new Chart(pCanvas, {\n          type: 'doughnut',\n          data: {\n            labels: validAssets.map(a => a.name),\n            datasets: [{\n              data: validAssets.map(a => a.fv),\n              backgroundColor: ['#1a4a6b', '#1a6b47', '#6b4e1a', '#b85c00', '#6b1a1a', '#a09d98'],\n              borderWidth: 1,\n              borderColor: '#f7f6f2'\n            }]\n          },\n          options: {\n            responsive: true,\n            plugins: {\n              legend: { display: false }\n            },\n            cutout: '70%'\n          }\n        });\n      }\n\n      // Chart 2: Goals Bar Projections (Target vs. Projected)\n      const validGoals = state.newGoalsEnabled ? state.newGoals : [];\n      if (validGoals.length === 0) {\n        const ctx = gCanvas.getContext('2d');\n        ctx.clearRect(0,0,gCanvas.width,gCanvas.height);\n        ctx.fillStyle = '#a09d98';\n        ctx.font = '12px DM Sans';\n        ctx.textAlign = 'center';\n        ctx.fillText('No financial targets configured.', gCanvas.width/2, 100);\n      } else {\n        goalsChartInst = new Chart(gCanvas, {\n          type: 'bar',\n          data: {\n            labels: validGoals.map(g => g.name),\n            datasets: [\n              {\n                label: 'Required Goal (RM)',\n                data: validGoals.map(g => g.target),\n                backgroundColor: 'rgba(200, 196, 187, 0.45)',\n                borderWidth: 1,\n                borderRadius: 4\n              },\n              {\n                label: 'Projected Output (RM)',\n                data: validGoals.map(g => g.calculatedFv),\n                backgroundColor: '#1a4a6b',\n                borderWidth: 1,\n                borderRadius: 4\n              }\n            ]\n          },\n          options: {\n            responsive: true,\n            scales: {\n              y: {\n                beginAtZero: true,\n                grid: { color: '#e2dfd8' },\n                ticks: { color: '#6b6860', font: { family: 'DM Mono' } }\n              },\n              x: {\n                grid: { display: false },\n                ticks: { color: '#6b6860', font: { family: 'DM Sans', size: 10 } }\n              }\n            },\n            plugins: {\n              legend: { position: 'bottom', labels: { boxWidth: 12, font: { family: 'DM Sans', size: 11 } } }\n            }\n          }\n        });\n      }\n    }\n\n\n    // Formatting tools\n    function formatCurrency(v) {\n      return new Intl.NumberFormat('en-MY', {\n        style: 'currency',\n        currency: 'MYR',\n        minimumFractionDigits: 2,\n        maximumFractionDigits: 2\n      }).format(v);\n    }\n\n  </script>\n</body>\n</html>";

window.WQPlanningSuiteModules = window.WQPlanningSuiteModules || [];
window.WQPlanningSuiteModules.push({
  id: "investment",
  title: "Investment Planning",
  render(container) {
    container.innerHTML = '';
    const frame = document.createElement('iframe');
    frame.className = 'planning-suite-frame';
    frame.title = "Investment Planning";
    frame.srcdoc = window.WQStorage?.injectScopedStorageIntoHtml?.(html, this.id) || html;
    const resizeFrame = () => {
      try {
        const doc = frame.contentDocument || frame.contentWindow?.document;
        if (!doc) return;
        const h = Math.max(760, doc.documentElement.scrollHeight, doc.body?.scrollHeight || 0);
        frame.style.height = `${h + 32}px`;
      } catch (_) {}
    };
    frame.addEventListener('load', () => {
      resizeFrame();
      let runs = 0;
      const timer = setInterval(() => {
        resizeFrame();
        runs += 1;
        if (runs > 12) clearInterval(timer);
      }, 500);
    });
    container.appendChild(frame);
  }
});

})();
